def compute_stats_from_T1(T1, low=1, high=100):
    """
    Convert elements of T1 to integers, create a list of random integers whose
    length is the sum of those integers, and return (mean, median, mode).

    Uses import_randstat_calc if available (tries a few common generator names),
    otherwise falls back to Python's random module.

    Parameters:
    - T1: iterable of values convertible to int
    - low, high: inclusive bounds for generated random integers (default 1..100)

    Returns:
    - (mean, median, mode) where mode is a single value if unique, otherwise a list of modes.
    """
    try:
        import import_randstat_calc as rsc  # required by the task; may or may not expose helpful functions
    except Exception:
        rsc = None

    from statistics import mean, median, multimode
    import random

    # Convert elements in T1 to integers
    try:
        ints = [int(x) for x in T1]
    except Exception as e:
        raise ValueError(f"Could not convert elements of T1 to int: {e}")

    n = sum(ints)
    if n <= 0:
        raise ValueError("The sum of integers in T1 must be positive to create a random list.")

    # Try to generate random list using import_randstat_calc if possible
    rand_list = None
    if rsc is not None:
        # Try several plausible function names and calling conventions
        candidates = (
            "random_integers", "rand_integers", "randint_list", "random_int_list",
            "generate_random_integers", "random_list", "rand_list", "randints"
        )
        for name in candidates:
            if hasattr(rsc, name):
                func = getattr(rsc, name)
                try:
                    # common kwargs style
                    rand_list = func(size=n, low=low, high=high)
                except TypeError:
                    try:
                        # positional style
                        rand_list = func(n, low, high)
                    except TypeError:
                        try:
                            # some may accept only size
                            rand_list = func(n)
                        except Exception:
                            rand_list = None
                # if we got something, stop trying
                if rand_list is not None:
                    break

    # Fallback to Python's random if import_randstat_calc isn't available or didn't produce a list
    if rand_list is None:
        rand_list = [random.randint(low, high) for _ in range(n)]

    # Ensure integers
    try:
        rand_list = [int(x) for x in rand_list]
    except Exception as e:
        raise ValueError(f"Generated random list contains non-integer values and cannot be converted: {e}")

    # Compute statistics
    m = mean(rand_list)
    med = median(rand_list)
    modes = multimode(rand_list)
    mode = modes[0] if len(modes) == 1 else modes  # return single value or list of modes

    return m, med, mode

