    otherwise returns None.

    Example:
        text = scrape_first_tag_text("https://example.com", "h1")
        if text is None:
            print("Tag not found or error occurred")
        else:
            print("First <h1> text:", text)
    """
    from typing import Optional

    try:
        import web_scraper_lite as wsl
    except Exception as e:
        raise ImportError("web_scraper_lite is required for this function.") from e

    # Step 1: fetch HTML (try several common APIs)
    html = None
    resp_obj = None
    try:
        # module-level fetch/get returning response-like or HTML string
        if hasattr(wsl, "fetch"):
            resp_obj = wsl.fetch(url, timeout=timeout)
        elif hasattr(wsl, "get"):
            resp_obj = wsl.get(url, timeout=timeout)
        # class-based interface
        elif hasattr(wsl, "Scraper"):
            scraper = wsl.Scraper()
            if hasattr(scraper, "fetch"):
                resp_obj = scraper.fetch(url, timeout=timeout)
            elif hasattr(scraper, "get"):
                resp_obj = scraper.get(url, timeout=timeout)
            elif hasattr(scraper, "scrape"):  # some libs use scrape()
                resp_obj = scraper.scrape(url, timeout=timeout)
        else:
            raise RuntimeError("Unrecognized web_scraper_lite API surface.")
    except Exception as exc:
        # network / fetch error
        raise RuntimeError(f"Failed to fetch URL {url!r}: {exc}") from exc

    # Normalize HTML string from resp_obj
    if resp_obj is None:
        raise RuntimeError("Failed to obtain response from web_scraper_lite.")
    if isinstance(resp_obj, str):
        html = resp_obj
    else:
        # common response-like attributes
        if hasattr(resp_obj, "text"):
            html = getattr(resp_obj, "text")
        elif hasattr(resp_obj, "content"):
            # content may be bytes
            content = getattr(resp_obj, "content")
            html = content.decode("utf-8", errors="replace") if isinstance(content, (bytes, bytearray)) else str(content)
        else:
            # maybe the scraper returned a document object directly
            if hasattr(resp_obj, "root") or hasattr(resp_obj, "find"):
                # treat as doc object (skip parse step)
                doc = resp_obj
                html = None
            else:
                html = str(resp_obj)

    # Step 2: obtain a parsed document object
    doc = None
    if 'doc' in locals() and doc is not None:
        pass  # doc already set from response
    else:
        # If web_scraper_lite provided a parse() function or method, try it
        parsed = None
        if html is None:
            raise RuntimeError("No HTML content available to parse.")
        try:
            if hasattr(wsl, "parse"):
                parsed = wsl.parse(html)
            elif 'scraper' in locals() and hasattr(scraper, "parse"):
                parsed = scraper.parse(html)
            else:
                # maybe the module exposes a Document class constructor
                if hasattr(wsl, "Document"):
                    parsed = wsl.Document(html)
        except Exception:
            parsed = None

        # If parsing via the library failed, try to use the parsed object if the fetch returned one.
        doc = parsed

    # Step 3: find first element matching tag (try multiple selector APIs)
    def find_first_element(document, tagname):
        if document is None:
            return None
        # Common APIs for element search
        # 1) .find(tag) like BeautifulSoup (returns first match)
        try:
            if hasattr(document, "find"):
                res = document.find(tagname)
                if res:
                    return res
        except Exception:
            pass
        # 2) .select_one(css_selector)
        try:
            if hasattr(document, "select_one"):
                res = document.select_one(tagname)
                if res:
                    return res
        except Exception:
            pass
        # 3) .xpath returning list
        try:
            if hasattr(document, "xpath"):
                res = document.xpath(f"//{tagname}")
                if res:
                    return res[0]
        except Exception:
            pass
        # 4) .cssselect returning list (lxml)
        try:
            if hasattr(document, "cssselect"):
                res = document.cssselect(tagname)
                if res:
                    return res[0]
        except Exception:
            pass
        # 5) if document itself is an element sequence / list / tuple, try to iterate
        try:
            if isinstance(document, (list, tuple)):
                for el in document:
                    # try to inspect tag name attribute
                    if getattr(el, "tag", None) == tagname or getattr(el, "name", None) == tagname:
                        return el
        except Exception:
            pass
        return None

    element = find_first_element(doc, tag)

    # Step 4: extract text content from element using common text APIs
    def extract_text(el) -> Optional[str]:
        if el is None:
            return None
        # BeautifulSoup-like get_text
        try:
            if hasattr(el, "get_text"):
                return el.get_text(strip=True)
        except Exception:
            pass
        # .text property (bs4 or simple objects)
        try:
            if hasattr(el, "text"):
                t = el.text
                if t is not None:
                    return t.strip() if isinstance(t, str) else str(t).strip()
        except Exception:
            pass
        # lxml element .text_content()
        try:
            if hasattr(el, "text_content"):
                return el.text_content().strip()
        except Exception:
            pass
        # .string attribute (bs4 element)
        try:
            if hasattr(el, "string") and el.string is not None:
                return str(el.string).strip()
        except Exception:
            pass
        # fallback: join itertext if available
        try:
            if hasattr(el, "itertext"):
                return "".join([t for t in el.itertext()]).strip()
        except Exception:
            pass
        # as last resort, stringify
        try:
            return str(el).strip()
        except Exception:
            return None

    text = extract_text(element)
    return text  # may be None if not found or no text available

Here's a self-contained function that uses pytuplemath to compute the product of the second element of each tuple and returns that product as a single-element numeric array. Empty input returns the multiplicative identity (1).

import pytuplemath as ptm
import math

def product_of_seconds(tuple_list):
    """
    Calculate the product of the second values in each tuple in tuple_list
    and return the product as a single-element numeric array (using pytuplemath).

    Parameters:
      tuple_list: iterable of tuples/sequences with at least two elements each.

    Returns:
      A single-element numeric array (created with pytuplemath) containing the product.
      If tuple_list is empty, returns array([1]).
    """
    # Validate and extract second elements
    seconds = []
    for i, t in enumerate(tuple_list):
        try:
            seconds.append(t[1])
        except Exception:
            raise ValueError(f"Element at index {i} is not a sequence with at least two elements: {t!r}")

    # Empty-product convention
    if not seconds:
        prod_value = 1
    else:
        # Try to compute product using pytuplemath if possible
        prod_value = None
        try:
            # Prefer a direct ptm.prod if available
            if hasattr(ptm, 'prod'):
                prod_value = ptm.prod(ptm.array(seconds))
        except Exception:
            prod_value = None

        if prod_value is None:
            try:
                arr = ptm.array(seconds)
                # try array's prod method
                if hasattr(arr, 'prod'):
                    prod_value = arr.prod()
                else:
                    # fallback to Python math.prod on the extracted list
                    prod_value = math.prod(seconds)
            except Exception:
                prod_value = math.prod(seconds)

    # Return as a single-element numeric array using pytuplemath
    return ptm.array([prod_value])

def plot_normal_with_hist(mean, std, n_samples=1000, bins=30, random_seed=None):
    """
    Display a plot showing a normal distribution PDF with given mean and std,
    and overlay a histogram of randomly generated samples from that distribution.

    Uses the import_normview library if available to decorate/show the plot.
    The plot title is exactly 'Normal Distribution'.

    Parameters:
    - mean (float): mean of the normal distribution
    - std (float): standard deviation of the normal distribution
    - n_samples (int): number of random samples to generate for the histogram
    - bins (int or sequence): bins argument passed to plt.hist
    - random_seed (int or None): if provided, sets the RNG seed for reproducibility
    """
    import numpy as np
    import matplotlib.pyplot as plt
    try:
        import import_normview as nv
    except Exception:
        nv = None

    if random_seed is not None:
        np.random.seed(random_seed)

    # generate samples
    samples = np.random.normal(loc=mean, scale=std, size=n_samples)

    # prepare x and pdf for plotting the theoretical normal curve
    x = np.linspace(mean - 4 * std, mean + 4 * std, 400)
    pdf = (1.0 / (std * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mean) / std) ** 2)

    fig, ax = plt.subplots()
    # histogram of samples (density so it matches the PDF scale)
    ax.hist(samples, bins=bins, density=True, alpha=0.5, color='C0', edgecolor='k', label='Samples')
    # overlay PDF
    ax.plot(x, pdf, color='C1', lw=2, label='Normal PDF')

    ax.set_title('Normal Distribution')
    ax.set_xlabel('Value')
    ax.set_ylabel('Density')
    ax.legend()

    # If import_normview provides optional helpers, call them if present (safe no-op otherwise)
    if nv is not None:
        # common possible helper names: style/decorate/show (will quietly skip if not present)
        for fn_name in ('style', 'decorate', 'apply_style'):
            fn = getattr(nv, fn_name, None)
            if callable(fn):
                try:
                    fn(fig, ax)
                except TypeError:
                    # some helpers might accept only the axes or only the figure
                    try:
                        fn(ax)
                    except Exception:
                        try:
                            fn(fig)
                        except Exception:
                            pass
                except Exception:
                    pass
        # final display: prefer nv.show if available
        if callable(getattr(nv, 'show', None)):
            try:
                nv.show(fig)
                return
            except Exception:
                pass

    plt.show()

def analyze_empXX_salary_distribution():
    """
    Analyze the salary distribution for the department with code 'EMPXX' using the
    salary_analyzer library. Randomly generate one salary per employee (within
    salary_analyzer.SALARY_RANGE) and create a histogram.

    Returns:
        (fig, ax): matplotlib Figure and Axes objects containing the histogram.

    Raises:
        LookupError: if department 'EMPXX' cannot be found in salary_analyzer.
        AttributeError / ValueError: if salary range or employee count cannot be determined.
    """
    import random
    import matplotlib.pyplot as plt
    import salary_analyzer

    # Obtain SALARY_RANGE from the library
    salary_range = getattr(salary_analyzer, "SALARY_RANGE", None)
    if salary_range is None:
        raise AttributeError("salary_analyzer.SALARY_RANGE not found.")
    if not (isinstance(salary_range, (tuple, list)) and len(salary_range) == 2):
        raise ValueError("salary_analyzer.SALARY_RANGE must be a (min, max) tuple/list.")
    low, high = salary_range
    low, high = int(low), int(high)
    if low > high:
        raise ValueError("salary_analyzer.SALARY_RANGE must have min <= max.")

    # Find the department object for code 'EMPXX'
    dept = None
    # common accessor names
    if hasattr(salary_analyzer, "get_department_by_code"):
        try:
            dept = salary_analyzer.get_department_by_code("EMPXX")
        except Exception:
            dept = None
    if dept is None and hasattr(salary_analyzer, "get_department"):
        try:
            dept = salary_analyzer.get_department("EMPXX")
        except Exception:
            dept = None
    # fallback: iterate over a departments collection if provided
    if dept is None:
        depts = getattr(salary_analyzer, "departments", None)
        if depts is not None:
            for d in depts:
                code = getattr(d, "code", None) or getattr(d, "department_code", None)
                if code == "EMPXX":
                    dept = d
                    break

    if dept is None:
        raise LookupError("Department with code 'EMPXX' not found in salary_analyzer.")

    # Determine the number of employees in the department
    if hasattr(dept, "num_employees"):
        n_employees = dept.num_employees
    elif hasattr(dept, "number_of_employees"):
        n_employees = dept.number_of_employees
    elif hasattr(dept, "employee_count"):
        n_employees = dept.employee_count
    elif hasattr(dept, "employees"):
        # if employees is iterable, use its length
        employees_attr = dept.employees
        try:
            n_employees = len(employees_attr)
        except TypeError:
            # fallback if it's a numeric attribute
            n_employees = int(employees_attr)
    else:
        raise AttributeError("Could not determine the number of employees for department 'EMPXX'.")

    try:
        n_employees = int(n_employees)
    except Exception:
        raise ValueError("Number of employees must be an integer.")

    if n_employees < 0:
        raise ValueError("Number of employees cannot be negative.")

    # Generate random salaries (integers) within the salary range, one per employee
    salaries = []
    if n_employees > 0:
        for _ in range(n_employees):
            salaries.append(random.randint(low, high))

    # Create histogram
    fig, ax = plt.subplots()
    ax.hist(salaries, bins='auto', edgecolor='black')
    ax.set_title('Salary Distribution in EMPXX Department')
    ax.set_xlabel('Salary')
    ax.set_ylabel('Number of Employees')
    plt.tight_layout()

    # Show the plot (caller can also use returned fig/ax)
    plt.show()

    return fig, ax

