import socket
import ipaddress
from typing import Optional, Dict, Any
import json

def geolocate_host(host: str, ipinfo_token: Optional[str] = None, timeout: float = 5.0) -> Dict[str, Any]:
    """
    Resolve a hostname to an IP address and fetch geolocation information using the
    ipgeolocator library if available, otherwise falling back to ipinfo.io HTTP API.

    Returns a dict with keys:
      - success: bool
      - ip: resolved IP (str) or None
      - provider: 'ipgeolocator', 'ipinfo_direct', or None
      - data: provider response dict when success is True
      - error: error message when success is False
      - details: optional more info (e.g. exception messages)

    Parameters:
      - host: hostname or IP string to resolve/lookup.
      - ipinfo_token: optional ipinfo.io token to include (if required/available).
      - timeout: network timeout for any HTTP calls (seconds).
    """
    result: Dict[str, Any] = {
        "success": False,
        "ip": None,
        "provider": None,
        "data": None,
        "error": None,
        "details": None,
    }

    # Validate input
    if not isinstance(host, str) or not host.strip():
        result["error"] = "Invalid host parameter (must be a non-empty string)."
        return result
    host = host.strip()

    # If host is already an IP, accept it; otherwise resolve DNS
    ip_str = None
    try:
        # Accept direct IPv4/IPv6 strings
        try:
            ip_obj = ipaddress.ip_address(host)
            ip_str = str(ip_obj)
        except ValueError:
            # Not a direct IP, try DNS resolution
            # Prefer IPv4 but accept the first found address (IPv4 or IPv6)
            addrs = socket.getaddrinfo(host, None)
            if not addrs:
                raise socket.gaierror(f"No address records for host: {host}")
            # Find the first address family entry and extract the address
            addr = None
            for entry in addrs:
                # entry[4] is the sockaddr tuple; IPv4: (ip, port), IPv6: (ip, port, flow, scope)
                sa = entry[4]
                if sa:
                    addr = sa[0]
                    if addr:
                        ip_str = addr
                        break
            if not ip_str:
                raise socket.gaierror(f"Could not extract IP from getaddrinfo results for: {host}")
    except (socket.gaierror, OSError) as e:
        result["error"] = f"DNS resolution failed for host: {host}"
        result["details"] = str(e)
        return result
    except Exception as e:
        result["error"] = "Unexpected error while resolving host."
        result["details"] = str(e)
        return result

    result["ip"] = ip_str

    # Try to use ipgeolocator library if available and appears usable
    try:
        import ipgeolocator  # type: ignore
        _ipg = ipgeolocator

        # Try several common function/class names/usage patterns.
        def _try_call(fn, *args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except TypeError:
                # Try without extra kwargs if signature incompatible
                return fn(*args)
        # candidate free functions
        for fname in ("get", "locate", "lookup", "geolocate", "find", "query"):
            fn = getattr(_ipg, fname, None)
            if callable(fn):
                try:
                    # first try basic call
                    data = _try_call(fn, ip_str)
                    result.update({"success": True, "provider": "ipgeolocator", "data": data})
                    return result
                except Exception:
                    # try with provider/token kwargs that some wrappers need
                    try:
                        data = fn(ip_str, provider="ipinfo", token=ipinfo_token)  # type: ignore
                        result.update({"success": True, "provider": "ipgeolocator", "data": data})
                        return result
                    except Exception:
                        # keep trying other patterns
                        pass

        # candidate classes to instantiate
        for clsname in ("IpGeolocator", "IPGeolocator", "GeoLocator", "Geolocator", "Locator"):
            cls = getattr(_ipg, clsname, None)
            if cls:
                try:
                    # try constructing with provider/token if possible
                    try:
                        inst = cls(provider="ipinfo", token=ipinfo_token)  # type: ignore
                    except TypeError:
                        inst = cls()  # type: ignore
                except Exception:
                    inst = None
                if inst:
                    for mname in ("get", "locate", "lookup", "geolocate", "find"):
                        m = getattr(inst, mname, None)
                        if callable(m):
                            try:
                                data = m(ip_str)
                                result.update({"success": True, "provider": "ipgeolocator", "data": data})
                                return result
                            except Exception:
                                try:
                                    data = m(ip_str, provider="ipinfo", token=ipinfo_token)  # type: ignore
                                    result.update({"success": True, "provider": "ipgeolocator", "data": data})
                                    return result
                                except Exception:
                                    pass
        # If we reach here, ipgeolocator was imported but no usable API call succeeded.
        ipgeolocator_error = "ipgeolocator module present but no compatible API call succeeded."
    except Exception as e:
        # ipgeolocator not available or import failed
        ipgeolocator_error = f"ipgeolocator import/usage failed: {e}"

    # Fallback: direct request to ipinfo.io
    try:
        import requests  # type: ignore
    except Exception as e:
        result["error"] = "Neither ipgeolocator nor requests are usable to perform a lookup."
        result["details"] = f"ipgeolocator info: {ipgeolocator_error}; requests import error: {e}"
        return result

    # Build URL and params
    url = f"https://ipinfo.io/{ip_str}/json"
    params = {}
    if ipinfo_token:
        params["token"] = ipinfo_token

    try:
        resp = requests.get(url, params=params, timeout=timeout)
    except Exception as e:
        result["error"] = f"Network error while querying ipinfo.io for {ip_str}"
        result["details"] = str(e)
        return result

    # Inspect HTTP response
    try:
        resp_text = resp.text
    except Exception:
        resp_text = None

    if resp.status_code != 200:
        # Try to extract JSON message if present
        msg = None
        try:
            msg = resp.json()
        except Exception:
            msg = resp_text
        result["error"] = f"ipinfo.io returned HTTP {resp.status_code}"
        result["details"] = msg
        return result

    # Try to parse JSON
    try:
        data = resp.json()
    except Exception as e:
        # Some services might return non-JSON; include raw text
        result["error"] = "ipinfo.io returned invalid JSON"
        result["details"] = {"exception": str(e), "raw_text": resp_text}
        return result

    # Success
    result.update({"success": True, "provider": "ipinfo_direct", "data": data})
    return result
