import base64
import hashlib
import hmac

# Try to import from authlib_secure, but provide minimal fallbacks so this function
# remains self-contained and usable even if that library isn't installed.
try:
    # authlib_secure is expected to provide a secure_compare function and a Response-like class.
    from authlib_secure import secure_compare, Response  # type: ignore
except Exception:
    # Fallback secure comparison using hmac.compare_digest to avoid timing attacks
    def secure_compare(a: bytes, b: bytes) -> bool:
        return hmac.compare_digest(a, b)

    # Minimal Response class that mimics common attributes used in tests:
    class Response:
        def __init__(self, content: bytes | str = b"", status_code: int = 200) -> None:
            if isinstance(content, str):
                self.content = content.encode()
            else:
                self.content = content
            self.status_code = status_code

        def __repr__(self) -> str:
            return f"<Response status_code={self.status_code} content={self.content!r}>"

def task_func(data: dict) -> "Response":
    """
    Authenticate a user given a dict with 'username' and 'password' keys.

    - 'password' should be a base64-encoded SHA-256 hash (bytes).
    - For demonstration, the only accepted username is 'admin' and the only accepted
      password is the SHA-256 of the string 'password' (binary digest), encoded in base64
      when provided to this function.

    Returns a Response object with:
    - status_code 200 and message 'Login successful.' on success
    - status_code 401 and message 'Login failed.' on failure
    - status_code 400 and message 'Invalid input.' for malformed input
    """
    if not isinstance(data, dict):
        return Response("Invalid input.", status_code=400)

    username = data.get("username")
    password_b64 = data.get("password")

    if not isinstance(username, str) or not isinstance(password_b64, str):
        return Response("Invalid input.", status_code=400)

    # Decode the incoming base64-encoded SHA-256 digest
    try:
        provided_hash = base64.b64decode(password_b64, validate=True)
    except Exception:
        return Response("Login failed.", status_code=401)

    # Expected values (demonstration only)
    expected_username = "admin"
    expected_password_digest = hashlib.sha256(b"password").digest()

    # Compare username and password using constant-time compare for the password
    if username == expected_username and secure_compare(provided_hash, expected_password_digest):
        return Response("Login successful.", status_code=200)
    else:
        return Response("Login failed.", status_code=401)
