def simulate_petshop_sales(animals, mu, seed=None):
    """
    Simulate pet shop sales where the number of customers follows a Poisson(mu).
    Each customer buys exactly one animal chosen uniformly at random from `animals`.
    Uses the petshop_simulator package when available for sampling (falls back to numpy/random).

    Parameters
    - animals: list of str
        List of animal types available for purchase (must be non-empty).
    - mu: float
        Mean of the Poisson distribution for the number of customers (mu >= 0).
    - seed: int or None
        Optional RNG seed to make the simulation reproducible.

    Returns
    - summary: dict
        {
          'total_customers': int,
          'sales': { animal_name: int, ... }
        }
    The function also prints a short human-readable summary.
    """
    # Basic validation
    if not isinstance(animals, (list, tuple)) or len(animals) == 0:
        raise ValueError("`animals` must be a non-empty list or tuple of animal names.")
    if mu < 0:
        raise ValueError("`mu` must be non-negative.")

    # Attempt to import petshop_simulator (required by the task)
    try:
        import petshop_simulator as pss
    except Exception as e:
        raise ImportError(
            "petshop_simulator is required for this function. "
            "Import failed with: {}".format(e)
        )

    # Set seeds where possible for reproducibility
    import random
    try:
        import numpy as np
    except Exception:
        np = None

    if seed is not None:
        try:
            random.seed(seed)
        except Exception:
            pass
        if np is not None:
            try:
                np.random.seed(seed)
            except Exception:
                pass
        # try to set seed on petshop_simulator if it exposes a seeding function
        try:
            if hasattr(pss, "seed"):
                # some libraries expose seed()
                pss.seed(seed)
            elif hasattr(pss, "set_seed"):
                pss.set_seed(seed)
            elif hasattr(pss, "rng") and hasattr(pss.rng, "seed"):
                pss.rng.seed(seed)
            elif hasattr(pss, "random") and hasattr(pss.random, "seed"):
                pss.random.seed(seed)
        except Exception:
            # non-fatal if the library doesn't support a common API
            pass

    # Function to sample a Poisson number of customers, trying petshop_simulator first,
    # then numpy, then an internal algorithm.
    def sample_poisson(lam):
        # Try petshop_simulator-provided poisson sampler(s)
        for candidate in (
            getattr(pss, "poisson", None),
            getattr(getattr(pss, "random", None), "poisson", None),
            getattr(getattr(pss, "rng", None), "poisson", None),
            getattr(getattr(pss, "np", None), "random", None) and getattr(pss.np.random, "poisson", None),
        ):
            if callable(candidate):
                try:
                    return int(candidate(lam))
                except Exception:
                    # ignore and try next
                    pass
        # Try numpy
        if np is not None:
            try:
                return int(np.random.poisson(lam))
            except Exception:
                pass
        # Fallback: Knuth's algorithm (works for moderate lam)
        import math, random as _rnd
        L = math.exp(-lam)
        k = 0
        p = 1.0
        while p > L:
            k += 1
            p *= _rnd.random()
        return k - 1

    # Function to pick a random animal; prefer petshop_simulator choice if available
    def pick_one(seq):
        # Try library-provided choice functions
        for choice_func in (
            getattr(pss, "choice", None),
            getattr(getattr(pss, "random", None), "choice", None),
            getattr(getattr(pss, "rng", None), "choice", None),
            getattr(getattr(pss, "np", None), "random", None) and getattr(pss.np.random, "choice", None),
        ):
            if callable(choice_func):
                try:
                    return choice_func(seq)
                except Exception:
                    pass
        # Fallback to Python's random.choice
        return random.choice(seq)

    # Sample number of customers
    n_customers = sample_poisson(mu)
    if n_customers < 0:
        n_customers = 0

    # Initialize counts
    sales = {animal: 0 for animal in animals}

    # Simulate purchases
    for _ in range(n_customers):
        animal_bought = pick_one(animals)
        # ensure returned type is hashable string; convert if necessary
        try:
            key = str(animal_bought)
            # If the choice returns an object equal to a name in the animals list,
            # prefer matching exact value to keep keys identical to input list
            if animal_bought in animals:
                key = animal_bought
        except Exception:
            key = animal_bought
        # If key not in our provided animals (unlikely), map to string name if possible
        if key not in sales:
            # try to find match by string representation
            found = None
            for a in animals:
                if str(a) == str(key):
                    found = a
                    break
            if found is not None:
                sales[found] += 1
