def plot_random_3d_scatter(n=500, seed=None, color='blue', size=5, return_points=False):
    """
    Generate n random 3D points in [0, 1) for each coordinate and draw a 3D scatter
    using the scatter3d_gen library.

    Parameters:
    - n (int): number of points to generate (default 500)
    - seed (int|None): RNG seed for reproducibility (default None)
    - color: color spec passed to the plotting function if supported (default 'blue')
    - size: marker size passed to the plotting function if supported (default 5)
    - return_points (bool): if True, return the (n,3) numpy array of generated points

    Notes:
    - This function tries several common APIs that scatter3d_gen might expose:
      - scatter3d_gen.scatter3d(x, y, z, ...)
      - scatter3d_gen.scatter3d(points, ...)
      - scatter3d_gen.plot(...)
      - scatter3d_gen.Scatter3D().plot(...)
    - If the library is not installed or none of the detected APIs work, an informative
      ImportError / RuntimeError will be raised.
    """
    import numpy as np
    import inspect

    try:
        import scatter3d_gen
    except Exception as e:
        raise ImportError(
            "scatter3d_gen is required but could not be imported. "
            "Install it (e.g. pip install scatter3d_gen) and try again."
        ) from e

    rng = np.random.default_rng(seed)
    points = rng.random((n, 3))

    def try_call(func, pts):
        """
        Try calling func in multiple common ways. Return the value returned by func
        or raise the last exception encountered.
        """
        last_exc = None
        x, y, z = pts[:, 0], pts[:, 1], pts[:, 2]

        # Try positional (x, y, z)
        try:
            return func(x, y, z)
        except Exception as e:
            last_exc = e

        # Try kwargs x,y,z
        try:
            return func(x=x, y=y, z=z, color=color, size=size)
        except Exception as e:
            last_exc = e

        # Try passing whole points array as 'points' or 'data'
        for name in ('points', 'data', 'coords', 'xyz'):
            try:
                kwargs = {name: pts, 'color': color, 'size': size}
                return func(**kwargs)
            except Exception as e:
                last_exc = e

        # Try single array positional
        try:
            return func(pts)
        except Exception as e:
            last_exc = e

        # Try transposed array
        try:
            return func(pts.T)
        except Exception as e:
            last_exc = e

        # Nothing worked
        raise last_exc

    # Try several likely call targets in scatter3d_gen
    tried = []
    result = None
    # Common function names
    for name in ('scatter3d', 'scatter', 'plot_scatter3d', 'plot', 'scatter_plot'):
        if hasattr(scatter3d_gen, name):
            func = getattr(scatter3d_gen, name)
            if callable(func):
                tried.append(f'function {name}')
                try:
                    result = try_call(func, points)
                    break
                except Exception:
                    # continue trying other options
                    pass

    # Try class-based API e.g. Scatter3D()
    if result is None and hasattr(scatter3d_gen, 'Scatter3D'):
        TriedClass = getattr(scatter3d_gen, 'Scatter3D')
        try:
            inst = TriedClass()
            # try instance.plot or instance.scatter
            for mname in ('plot', 'scatter', 'scatter3d', 'draw'):
                if hasattr(inst, mname):
                    method = getattr(inst, mname)
                    if callable(method):
                        tried.append(f'Class Scatter3D method {mname}()')
                        try:
                            result = try_call(method, points)
                            break
                        except Exception:
                            pass
            # if instance itself is callable
            if result is None and callable(inst):
                tried.append('callable Scatter3D instance')
                try:
                    result = try_call(inst, points)
                except Exception:
                    pass
        except Exception:
            # constructing class failed; ignore
            pass

    if result is None:
        # As a last resort, if scatter3d_gen provides a generic "show" you might try to
        # create something directly, but we stop here and give guidance.
        raise RuntimeError(
            "Could not find a supported plotting API in scatter3d_gen. "
            "Functions/attributes tried: " + ", ".join(tried) + ".\n"
            "Please check the library's API and adapt this function accordingly."
        )

    # If result is a figure-like object with show() call it
    try:
        if hasattr(result, 'show') and callable(result.show):
            result.show()
    except Exception:
        # ignore errors from calling show
        pass

    if return_points:
        return points
    # otherwise return None

