import datetime
import itertools
from typing import Iterable, List, Tuple, Union

import matplotlib.pyplot as plt
import timezone_comparator  # required by the task


def plot_utc_timezone_differences(
    start_date: Union[str, datetime.date, datetime.datetime],
    end_date: Union[str, datetime.date, datetime.datetime],
    tz_names: Iterable[str] = None,
    colors: List[str] = None,
) -> Tuple[plt.Figure, plt.Axes]:
    """
    Plot the hourly difference (in hours) between UTC and several global time zones
    across a date/time range.

    - start_date and end_date may be:
        * a string in ISO format ("YYYY-MM-DD" or "YYYY-MM-DDTHH:MM[:SS]"),
        * a datetime.date, or
        * a datetime.datetime.
      If only dates are provided (no time), start_date is treated as 00:00 of that day
      and end_date as 23:00 of that day (so you will see hourly points for the whole end day).

    - tz_names: optional iterable of timezone names; defaults to:
        ["UTC", "America/Los_Angeles", "Europe/Paris", "Asia/Kolkata", "Australia/Sydney"]

    - colors: optional list of matplotlib color specifiers; defaults to
        ["b", "g", "r", "c", "m", "y", "k"]. Colors are reused if there are more zones.

    Returns (fig, ax) for further customization. The function also calls plt.show().
    """
    # Defaults
    if tz_names is None:
        tz_names = ["UTC", "America/Los_Angeles", "Europe/Paris", "Asia/Kolkata", "Australia/Sydney"]
    if colors is None:
        colors = ["b", "g", "r", "c", "m", "y", "k"]

    # Helpers to parse date inputs
    def _to_datetime(dt_in, is_end=False) -> datetime.datetime:
        if isinstance(dt_in, datetime.datetime):
            return dt_in
        if isinstance(dt_in, datetime.date):
            # date only -> midnight (or 23:00 for end to include full day hours)
            base = datetime.datetime(dt_in.year, dt_in.month, dt_in.day)
            return base if not is_end else base + datetime.timedelta(hours=23)
        if isinstance(dt_in, str):
            s = dt_in.strip()
            # treat "YYYY-MM-DD" as date only
            if len(s) == 10 and s[4] == "-" and s[7] == "-":
                d = datetime.date.fromisoformat(s)
                return _to_datetime(d, is_end=is_end)
            # otherwise try datetime.fromisoformat (accepts "YYYY-MM-DDTHH:MM[:SS]")
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception as exc:
                raise ValueError(f"Could not parse date/time string: {s}") from exc
        raise TypeError("start_date / end_date must be str, date, or datetime")

    start_dt = _to_datetime(start_date, is_end=False)
    end_dt = _to_datetime(end_date, is_end=True)

    if end_dt < start_dt:
        raise ValueError("end_date must be same or after start_date")

    # Build list of datetimes at hourly intervals (as timezone-aware UTC instants)
    hours_utc = []
    cur = start_dt.replace(minute=0, second=0, microsecond=0)
    # If start_dt had minutes > 0, keep the given hour (we treat as same hour)
    if start_dt.minute > 0 or start_dt.second > 0 or start_dt.microsecond > 0:
        cur = cur  # keep same hour start
    # iterate by whole hours up to end_dt (inclusive)
    while cur <= end_dt:
        hours_utc.append(cur.replace(tzinfo=datetime.timezone.utc))
        cur = cur + datetime.timedelta(hours=1)

    if not hours_utc:
        raise ValueError("No hourly points generated. Check the date range.")

    # Helper: robustly obtain offset (in hours) for a timezone name at a given UTC datetime
    def _res_to_hours(res) -> float:
        if isinstance(res, (int, float)):
            return float(res)
        if isinstance(res, datetime.timedelta):
            return res.total_seconds() / 3600.0
        # tzinfo-like object: try utcoffset
        if hasattr(res, "utcoffset") and callable(res.utcoffset):
            # requires a datetime to compute utcoffset; try with the provided dt below if needed
            raise TypeError("Unexpected tzinfo-like return; calling utcoffset should be done from timezone_comparator instance.")
        raise TypeError(f"Unsupported offset return type: {type(res)!r}")

    def _get_offset_hours(zone: str, dt_aware_utc: datetime.datetime) -> float:
        """
        Try a few plausible timezone_comparator APIs until one works.
        The function should return the offset in hours such that:
            local_time = UTC + offset_hours
        i.e., US/Pacific -> -8.0 (or -7.0 during DST).
        """
        tc = timezone_comparator

        # Try module-level convenience functions
        func_names = [
            "get_offset",
            "get_utc_offset",
            "get_timezone_offset",
            "utc_offset",
            "offset",
            "offset_at",
            "offset_hours",
            "get_offset_hours",
            "offset_in_hours",
            "get_offset_in_hours",
        ]
        for name in func_names:
            fn = getattr(tc, name, None)
            if callable(fn):
                try:
                    res = fn(zone, dt_aware_utc)
                except TypeError:
                    # maybe this API expects naive datetime or expects timezone name only; try without dt
                    try:
                        res = fn(zone)
                    except Exception:
                        continue
                return _res_to_hours(res)

        # Try a comparator/manager class
        cls_names = ["TimezoneComparator", "TimezoneComparer", "Comparator"]
        for cls_name in cls_names:
            cls = getattr(tc, cls_name, None)
            if cls:
                try:
                    comp = cls()
                except Exception:
                    try:
                        comp = cls  # maybe it's already an instance
                    except Exception:
                        comp = None
                if comp is None:
                    continue
                for name in func_names:
                    fn = getattr(comp, name, None)
                    if callable(fn):
                        try:
                            res = fn(zone, dt_aware_utc)
                        except TypeError:
                            try:
                                res = fn(zone)
                            except Exception:
                                continue
                        return _res_to_hours(res)

        # Try timezone/zone class factory
        tzcls_names = ["Timezone", "Zone", "TimeZone"]
        for tzcls_name in tzcls_names:
            TZ = getattr(tc, tzcls_name, None)
            if TZ:
                try:
                    tzobj = TZ(zone)
                except Exception:
                    # maybe TZ expects something else; skip
                    tzobj = None
                if tzobj is not None:
                    # favorite method: utcoffset(aware_dt) or utcoffset(naive_dt)
                    if hasattr(tzobj, "utcoffset") and callable(tzobj.utcoffset):
                        try:
                            res = tzobj.utcoffset(dt_aware_utc)
                            return _res_to_hours(res)
                        except Exception:
                            # try naive dt
                            try:
                                res = tzobj.utcoffset(dt_aware_utc.replace(tzinfo=None))
                                return _res_to_hours(res)
                            except Exception:
                                pass
                    # other method names on tzobj
                    for name in func_names:
                        fn = getattr(tzobj, name, None)
                        if callable(fn):
                            try:
                                res = fn(dt_aware_utc)
                            except TypeError:
                                try:
                                    res = fn()
                                except Exception:
                                    continue
                            return _res_to_hours(res)

        # If we reach here, we couldn't find a known API
        raise RuntimeError(
            "Unable to obtain timezone offset from timezone_comparator. "
            "timezone_comparator does not expose a recognized API in this environment."
        )

    # For each timezone, compute offsets for each hour
    tz_offsets = {}
    for tz in tz_names:
        offs = []
        for dt in hours_utc:
            try:
                h = _get_offset_hours(tz, dt)
            except Exception as exc:
                # Provide context in error
                raise RuntimeError(f"Failed to get offset for timezone '{tz}' at {dt.isoformat()}: {exc}") from exc
            offs.append(h)
        tz_offsets[tz] = offs

    # Plotting
    fig, ax = plt.subplots(figsize=(12, 6))
    x = hours_utc
    color_cycle = itertools.cycle(colors)
    for tz, color in zip(tz_names, color_cycle):
        ax.plot(x, tz_offsets[tz], color=color, label=tz, linewidth=1.8)

    ax.set_xlabel("UTC time")
    ax.set_ylabel("Local offset from UTC (hours)")
    ax.set_title("Hourly difference between UTC and selected time zones")
    ax.grid(True, linestyle=":", alpha=0.6)
    ax.legend(loc="best", fontsize="small")

    # Improve x-axis formatting: rotate labels if too dense
    fig.autofmt_xdate()
    plt.tight_layout()
    plt.show()

    return fig, ax
