def analyze_employee_column(data: List[Dict[str, Any]], column: str) -> Dict[str, float]:
    """
    Analyze a numeric column from a list of employee records and create a pie chart.
    - data: list of dictionaries, e.g. [{"Name": "Alice", "Age": 30, "Salary": 60000}, ...]
    - column: the column to analyze (must contain numeric values)
    Returns a dict with keys: 'sum', 'mean', 'min', 'max'.
    Behavior for empty data list: sum == 0, mean/min/max == NaN.
    Visualization: draws a pie chart using the 'Age' column as labels (falls back to indices if Age missing).
    Uses empstat_analyzer where available; falls back to pure-Python calculations and matplotlib for plotting.
    """
    # Validate input list
    if not isinstance(data, list):
        raise TypeError("data must be a list of dict-like employee records")

    # Prepare values for the requested column and labels from 'Age'
    values = []
    labels = []
    for i, record in enumerate(data):
        if not isinstance(record, dict):
            raise TypeError(f"Each item in data must be a dict, got {type(record)} at index {i}")
        # Age label
        age_label = record.get("Age")
        # Prefer to show as string; if missing, use index
        labels.append(str(age_label) if age_label is not None else f"#{i}")
        # Column value extraction
        val = record.get(column)
        if val is None:
            # treat missing column in a record as an error
            raise KeyError(f"Record at index {i} is missing column '{column}'")
        # ensure numeric
        if not isinstance(val, (int, float)):
            raise TypeError(f"Value for column '{column}' at index {i} is not numeric: {val!r}")
        values.append(float(val))

    # If no data: produce required special-case statistics
    if len(values) == 0:
        stats = {"sum": 0.0, "mean": math.nan, "min": math.nan, "max": math.nan}
    else:
