                    df_out = pd.concat([df_out, extra], ignore_index=True)
    else:
        # Fallback synthetic generation (Poisson)
        rng = np.random.default_rng()
        # Choose reasonable mean/hour rates (adjustable)
        mean_rates = { 'Car': 1200, 'Bus': 30, 'Truck': 150, 'Bike': 200 }
        generated = {col: rng.poisson(lam=mean_rates[col], size=len(times)) for col in vehicle_cols}
        df_out = pd.DataFrame({'Time': times})
        for col in vehicle_cols:
            df_out[col] = generated[col]

    # Save CSV with exact required column order
    df_out = df_out[['Time'] + vehicle_cols]
    df_out.to_csv(output_csv, index=False)

    # Plotting
    plt.figure(figsize=(10, 6))
    for col in vehicle_cols:
        plt.plot(df_out['Time'], df_out[col], marker='o', label=col)
    plt.xlabel('Time')
    plt.ylabel('Vehicle Count')
    plt.title('Traffic Counts by Vehicle Type')
    plt.legend()
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    return df_out
