Here's a self-contained Python function that computes the number of seconds until the next turn of the year in a given time zone from a given date string. It uses the time_until_new_year library when available; if that library is not installed or doesn't expose a suitable helper, the function falls back to a reliable local implementation using the standard library (zoneinfo) and dateutil when available for parsing.

Notes:
- date_str may be ISO-8601 or many common human-readable formats (dateutil.parser is used if available; otherwise datetime.fromisoformat is attempted).
- tz_str should be an IANA time zone name like "Europe/London", "America/New_York". If zoneinfo isn't available, it will try pytz.
- "Next turn of the year" is interpreted as the next occurrence of January 1st 00:00 in the given time zone strictly after the provided date/time. So if the provided date/time is exactly Jan 1 00:00, the next turn is one year later.

Code:

```python
from datetime import datetime, timezone
from typing import Optional

# Try to import the requested library (used if available)
try:
    import time_until_new_year as tuny  # optional helper library
except Exception:
    tuny = None

# Optional helpers for parsing and timezones
try:
    from dateutil import parser as _dateutil_parser
except Exception:
    _dateutil_parser = None

try:
    # Python 3.9+
    from zoneinfo import ZoneInfo  # preferred
    _ZoneInfo = ZoneInfo
    _USE_PYTZ = False
except Exception:
    _ZoneInfo = None
    _USE_PYTZ = True

if _USE_PYTZ:
    try:
        import pytz
    except Exception:
        pytz = None


def seconds_until_next_new_year(date_str: str, tz_str: str) -> int:
    """
    Return the number of seconds until the next turn of the year (Jan 1 00:00)
    in time zone `tz_str`, measured from the date/time represented by `date_str`.

    Parameters:
    - date_str: a date/time string (ISO-8601 recommended). If the parsed datetime
                is naive (no timezone), it will be interpreted in tz_str.
                If the parsed datetime is timezone-aware, it will be converted
                to tz_str.
    - tz_str:  an IANA time zone name, e.g. "Europe/London", "America/New_York".

    Uses the time_until_new_year library if available and exposing a suitable
    function; otherwise falls back to an internal implementation.

    Returns:
    - int: number of seconds strictly until the next Jan 1 00:00 in tz_str.
    """
    # 1) Try to use the time_until_new_year library if it exposes helpful functions.
    if tuny is not None:
        # Try several common function names and parameter styles.
        # We attempt progressively: (date_str, tz_str), (dt, tz_str), (dt,)
        try_names = [
            ("seconds_until_new_year", (date_str, tz_str)),
            ("time_until_new_year", (date_str, tz_str)),
            ("seconds_to_new_year", (date_str, tz_str)),
            # try passing a parsed datetime below if string variants fail
        ]
        for name, args in try_names:
            func = getattr(tuny, name, None)
            if callable(func):
                try:
                    return int(func(*args))
                except Exception:
                    # ignore and try next possibility
                    pass

    # 2) Parse the date string into a datetime
    dt: Optional[datetime] = None
    if _dateutil_parser is not None:
        try:
            dt = _dateutil_parser.parse(date_str)
        except Exception:
            dt = None
    if dt is None:
        # Try to cope with a common ISO format; handle 'Z' -> +00:00
        s = date_str.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(s)
        except Exception:
            # Last resort: try some common formats
            fmts = [
                "%Y-%m-%d %H:%M:%S",
                "%Y-%m-%d %H:%M",
                "%Y-%m-%d",
                "%d-%m-%Y %H:%M:%S",
                "%d-%m-%Y",
            ]
            for f in fmts:
                try:
                    dt = datetime.strptime(date_str, f)
                    break
                except Exception:
                    dt = None
            if dt is None:
                raise ValueError(f"Could not parse date string: {date_str!r}")

    # 3) Acquire tz info object
    tzinfo = None
    if _ZoneInfo is not None:
        try:
            tzinfo = _ZoneInfo(tz_str)
        except Exception as exc:
            raise ValueError(f"Unknown time zone for zoneinfo: {tz_str!r}") from exc
    else:
        if pytz is not None:
            try:
                tzinfo = pytz.timezone(tz_str)
            except Exception as exc:
                raise ValueError(f"Unknown time zone for pytz: {tz_str!r}") from exc
        else:
            raise RuntimeError("No zoneinfo or pytz available to handle time zones.")

    # 4) Make dt timezone-aware in the requested tz
    if dt.tzinfo is None:
        # naive datetime: interpret it in the requested timezone
        if _ZoneInfo is not None:
            dt = dt.replace(tzinfo=tzinfo)
        else:
            # pytz: localize
            dt = tzinfo.localize(dt)
    else:
        # tz-aware: convert it to requested timezone
        dt = dt.astimezone(tzinfo)

    # 5) Compute next new year in that timezone (Jan 1 00:00 of dt.year + 1)
    ny = datetime(dt.year + 1, 1, 1, 0, 0, 0)
    if _ZoneInfo is not None:
        ny = ny.replace(tzinfo=tzinfo)
    else:
        ny = tzinfo.localize(ny)

    delta = ny - dt
    # total_seconds could be fractional; return integer seconds
    return int(delta.total_seconds())
