import stem_counter

def _get_stemmer():
    if hasattr(stem_counter, "stem") and callable(stem_counter.stem):
        return lambda w: stem_counter.stem(w)
    if hasattr(stem_counter, "Stemmer"):
        s = stem_counter.Stemmer()
