            for api_name in ("convert_to_timezone", "to_timezone", "convert",
                             "parse_and_convert", "parse_timestamp"):
                if hasattr(tza, api_name):
                    func = getattr(tza, api_name)
                    # try calling; many libs accept (timestamp, tz_name)
                    try:
                        out = func(ts, tz_name)
                        # expect a datetime; if so, ensure tzinfo-aware in target tz
                        if isinstance(out, datetime):
                            return out
                        # if returns string, try to parse it below
                        if isinstance(out, str):
                            ts_str = out
                            break
                    except TypeError:
                        # maybe API signature is different; try (ts) then set tz separately
                        try:
                            out = func(ts)
                            if isinstance(out, datetime):
                                # try to convert timezone using a different tza helper if exists
                                if hasattr(tza, "set_timezone") and callable(getattr(tza, "set_timezone")):
                                    return getattr(tza, "set_timezone")(out, tz_name)
                                return out
                        except Exception:
                            pass
            else:
                ts_str = None
        else:
            ts_str = None

        # If we have a datetime already
        if isinstance(ts, datetime):
            dt = ts
        # if numeric epoch seconds
        elif isinstance(ts, (int, float)):
            dt = datetime.fromtimestamp(ts, tz=timezone.utc)
        else:
            # If timezone_averager returned a string representation, use that
            if ts_str is not None:
                parse_str = ts_str
            else:
                parse_str = ts

            # Basic ISO-8601 parsing using datetime.fromisoformat with small fixes:
            if isinstance(parse_str, str):
                s = parse_str
                # handle trailing 'Z' for UTC
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                try:
                    dt = datetime.fromisoformat(s)
                except Exception as e:
                    raise ValueError(f"Unable to parse timestamp string: {parse_str!r}") from e
            else:
                raise ValueError(f"Unsupported timestamp type: {type(ts)}")

        # Ensure dt is timezone-aware; if naive, assume it is in UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)

        # If timezone_averager provided direct conversion earlier (returned datetime), we already returned.
        # Now convert to requested tz using either timezone_averager (if available) or stdlib zoneinfo
        if tza is not None:
            # attempt to find a convert function that accepts a datetime and tz name
            for api_name in ("convert_to_timezone", "to_timezone", "convert",
                             "set_timezone", "change_timezone"):
                if hasattr(tza, api_name):
                    func = getattr(tza, api_name)
                    try:
                        out = func(dt, tz_name)
                        if isinstance(out, datetime):
                            return out
                        if isinstance(out, str):
                            s = out
                            if s.endswith("Z"):
                                s = s[:-1] + "+00:00"
                            try:
                                return datetime.fromisoformat(s)
                            except Exception:
                                break
                    except Exception:
                        continue

        # fallback conversion using stdlib zoneinfo
        try:
            from zoneinfo import ZoneInfo
        except Exception:
            raise ImportError("zoneinfo not available and timezone_averager conversion failed; cannot convert timezone")

        try:
            target_tz = ZoneInfo(tz_name)
        except Exception as e:
            raise ValueError(f"Unknown timezone name: {tz_name}") from e

        # convert dt to target timezone
        return dt.astimezone(target_tz)

    # Validate input
    ts_list = list(timestamps)
    if len(ts_list) < 2:
        raise ValueError("At least two timestamps are required to compute consecutive differences.")

    # Convert all timestamps
    converted = [_convert_single(ts) for ts in ts_list]

    # Compute absolute differences in seconds between consecutive items in original order
    diffs = []
    for a, b in zip(converted, converted[1:]):
        delta = (b - a).total_seconds()
        diffs.append(abs(delta))

    # Average
    avg = sum(diffs) / len(diffs)
    return avg

def analyze_prices(price_dict, bins=10, show_plot=True, save_path=None):
    """
    Process a dict of product_name -> price_string, convert prices to float,
    compute mean, median, standard deviation, and generate a histogram.

    Uses the optional `price_analyzer` library if available for parsing or stats;
    otherwise falls back to robust built-in parsing and the statistics module.

    Parameters:
    - price_dict: dict[str, str]  (e.g. {"apple": "1,234.56", "banana": "7.50"})
    - bins: int or sequence, number of bins for histogram (default 10)
    - show_plot: bool, whether to call plt.show() (default True)
    - save_path: optional str path to save the histogram image (e.g. "hist.png")

    Returns:
    dict with keys:
      - "mean", "median", "std" : floats
      - "prices" : dict of product_name -> float
      - "failed" : dict of product_name -> original_string for entries that couldn't be parsed
      - "fig" : matplotlib.figure.Figure object for the generated histogram (can be None if no data)
    """
    import re
    import statistics
    try:
        import price_analyzer  # optional; used if it provides helpers
    except Exception:
        price_analyzer = None

    # parsing helper: try price_analyzer.parse_price if provided, else use regex fallback
    def _parse_price_string(s):
        # If price_analyzer offers a parse function, try to use it
        if price_analyzer is not None and hasattr(price_analyzer, "parse_price"):
            try:
                return float(price_analyzer.parse_price(s))
            except Exception:
                pass

        # Fallback parsing:
        # - Remove currency symbols and whitespace
        # - Handle parentheses for negative values: "(1,234.56)" -> -1234.56
        # - Remove thousands separators (commas)
        # - Accept digits, optional decimal point and optional leading minus
        if s is None:
            raise ValueError("None price")
        s_orig = str(s).strip()

        neg = False
        if s_orig.startswith("(") and s_orig.endswith(")"):
            neg = True
            s_orig = s_orig[1:-1].strip()

        # Remove any chars except digits, dot, comma, minus
        cleaned = re.sub(r"[^0-9\.,\-]", "", s_orig)

        # If there are both comma and dot, assume comma is thousands separator (e.g. "1,234.56")
        # If there are commas only and multiple commas or no dot, treat commas as thousands separators.
        # This simple logic assumes decimal separator is dot.
        if "," in cleaned and "." in cleaned:
            # remove commas (thousands separator)
            cleaned = cleaned.replace(",", "")
        elif "," in cleaned and "." not in cleaned:
            # treat commas as thousands separators: remove them
            cleaned = cleaned.replace(",", "")

        # Now cleaned should be like "-1234.56" or "1234" etc.
        if cleaned in ("", ".", "-", "-."):
            raise ValueError(f"Unable to parse price string: '{s}'")

        try:
            value = float(cleaned)
        except Exception as e:
            raise ValueError(f"Unable to parse price string '{s}': {e}")

        return -value if neg else value

    # Parse all prices
    parsed = {}
    failed = {}
    for name, price_str in price_dict.items():
        try:
            value = _parse_price_string(price_str)
            parsed[name] = float(value)
        except Exception:
            failed[name] = price_str

    prices = list(parsed.values())
    if len(prices) == 0:
        return {"mean": None, "median": None, "std": None, "prices": parsed, "failed": failed, "fig": None}

    # Compute statistics: prefer price_analyzer stats if available and appropriate, else use statistics
    mean_val = None
    median_val = None
    std_val = None
    if price_analyzer is not None and hasattr(price_analyzer, "stats"):
        try:
            # try common names
            stats_mod = price_analyzer.stats
            if hasattr(stats_mod, "mean"):
                mean_val = float(stats_mod.mean(prices))
            if hasattr(stats_mod, "median"):
                median_val = float(stats_mod.median(prices))
            if hasattr(stats_mod, "std") or hasattr(stats_mod, "stdev"):
                std_func = getattr(stats_mod, "std", None) or getattr(stats_mod, "stdev", None)
                std_val = float(std_func(prices))
        except Exception:
            mean_val = median_val = std_val = None

    # Fallbacks if any are still None
    if mean_val is None:
        mean_val = statistics.mean(prices)
    if median_val is None:
        median_val = statistics.median(prices)
    if std_val is None:
        # Use population standard deviation (pstdev). Change to stdev(prices) for sample std.
        std_val = statistics.pstdev(prices)

    # Create histogram using matplotlib
    try:
        import matplotlib.pyplot as plt
    except Exception as e:
        # If matplotlib not available, return stats without figure
        return {"mean": mean_val, "median": median_val, "std": std_val, "prices": parsed, "failed": failed, "fig": None}

    fig, ax = plt.subplots()
    ax.hist(prices, bins=bins, edgecolor="black")
    ax.set_xlabel("Price")
    ax.set_ylabel("Count")
    ax.set_title("Price Distribution")

    # Draw lines for mean and median
    ax.axvline(mean_val, color="red", linestyle="--", linewidth=1.5, label=f"Mean: {mean_val:.2f}")
    ax.axvline(median_val, color="green", linestyle="-.", linewidth=1.5, label=f"Median: {median_val:.2f}")
    ax.legend()

    plt.tight_layout()

    if save_path:
        try:
            fig.savefig(save_path, bbox_inches="tight")
        except Exception:
            pass

    if show_plot:
        try:
            plt.show()
        except Exception:
            pass

    return {"mean": mean_val, "median": median_val, "std": std_val, "prices": parsed, "failed": failed, "fig": fig}


