        # This regex matches http/https URLs and also www. prefixed hosts.
        url_pattern = re.compile(
            r"""(?xi)
            \b
            (                               # Capture 1: entire matched URL
              (?:
                https?://                   # http:// or https://
                |                           #   or
                www\d{0,3}\.                # "www.", "www1.", "www2." ... (optional)
              )
              [^\s()<>{}\[\]]+              # Run of non-space, non-bracket characters
            )
            """
        )
        m = url_pattern.search(myString)
        if m:
            url = m.group(1)
