    # If image is float but outside [0,1], clip for display
    def _clip_for_display(a):
        if np.issubdtype(a.dtype, np.floating):
            # assume values might be 0..1 or 0..255; clip to [0,1] if near that, else scale
            if a.min() >= 0.0 and a.max() <= 1.0:
