    disp_filtered = _clip_for_display(show_filtered)

    # Display side-by-side
    fig, axes = plt.subplots(1, 2, figsize=figsize)
    ax0, ax1 = axes

    if disp_img.ndim == 2:
        ax0.imshow(disp_img, cmap=cmap or "gray")
    else:
