            x = np.linspace(x_min - 3 * std, x_max + 3 * std, 400)
        else:
            x = np.linspace(mean - 3 * std, mean + 3 * std, 400)
        pdf = (1.0 / (std * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mean) / std) ** 2)
