                                    cwd_files.append(os.path.join(os.getcwd(), fname))
                            if cwd_files:
                                return cwd_files
                        except Exception:
                            pass
                else:
                    # Single sheet: decide destination file path
                    if dest_path is None:
                        dest_file = _derive_target_file(src_dir, src_base, '.csv')
                    else:
                        if dest_is_dir:
                            dest_file = _derive_target_file(dest_path, src_base, '.csv')
                        else:
