    # Ensure destination directory exists
    dest_dirname = os.path.dirname(os.path.abspath(dest_file)) or '.'
    if not os.path.isdir(dest_dirname):
        os.makedirs(dest_dirname, exist_ok=True)

    df.to_csv(dest_file, index=include_index, encoding=encoding)
    return dest_file
